# find closed outlines (each color's cells forming loop) - simple approach: for each color, flood background
def regions(g, bg):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]
    out=[]
    for i in range(h):
        for j in range(w):
            if not seen[i][j] and g[i][j]!=bg:
                col=g[i][j]; st=[(i,j)]; seen[i][j]=True; reg=[]
                while st:
                    y,x=st.pop(); reg.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; st.append((ny,nx))
                out.append((col,len(reg)))
    return out
