                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; st.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                (r0,r1,c0,c1)=min(rs),max(rs),min(cs),max(cs)
                # fill interior only if it's a closed loop with bg inside
                inside=(c0-1>=0 and c1+1<w) and (r0-1>=0 and r1+1<h) and \
                    all(all(0<=y<h and 0<=x<w and g[y][x]!=col or False for x in range(c0,c1+1)) for y in range(r0,r1+1))
                # simpler: count cells of color==col on border vs area
