def f(g):
    h,w=len(g),len(g[0]); bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    out=[r[:] for r in g]; seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=set(); col=g[i][j]
                while st:
                    y,x=st.pop(); cells.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; st.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                perim=2*(r1-r0+1+c1-c0+1)-4
                border=sum(1 for y in range(r0,r1+1) for x in range(c0,c1+1) if (y==r0 or y==r1 or x==c0 or x==c1) and g[y][x]==col)
                if border==perim:
                    inter=(r1-r0-1)*(c1-c0-1)
                    fill=7 if inter%2==1 else 2
                    for y in range(r0+1,r1):
                        for x in range(c0+1,c1):
                            if g[y][x]!=col: out[y][x]=fill
    return out
